AssistantMessageToolRequest(name='create', tool_call_id='function-call-8fb0d790-e17c-4a6e-b0a8-fbc9f28c233f', arguments={'file_text': ":root {
    --primary-color: #1a1a1a;
    --secondary-color: #ffffff;
    --accent-color: #5c5c5c;
    --bg-color: #f9f9f9;
    --text-color: #333333;
    --light-gray: #e0e0e0;
    --badge-bg: #f0f0f0;
    --transition: all 0.3s ease;
    --container-width: 1200px;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Inter', sans-serif;
    line-height: 1.6;
    color: var(--text-color);
    background-color: var(--bg-color);
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 2rem;
}

section {
    padding: 5rem 0;
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition);
}

ul {
    list-style: none;
}

img {
    max-width: 100%;
    display: block;
}

.btn {
    display: inline-block;
    padding: 0.8rem 2rem;
    border-radius: 0;
    font-weight: 500;
    cursor: pointer;
    transition: var(--transition);
    border: 1px solid transparent;
}

.btn-primary {
    background-color: var(--primary-color);
    color: var(--secondary-color);
}

.btn-primary:hover {
    background-color: #333;
}

.btn-secondary {
    background-color: var(--secondary-color);
    color: var(--primary-color);
}

.btn-secondary:hover {
    background-color: var(--light-gray);
}

.badge {
    display: inline-block;
    padding: 0.3rem 0.8rem;
    background-color: var(--badge-bg);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 1rem;
}

/* Header & Nav */
header {
    background-color: var(--secondary-color);
    border-bottom: 1px solid var(--light-gray);
    position: sticky;
    top: 0;
    z-index: 1000;
}

nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 80px;
}

.logo {
    font-size: 1.5rem;
    font-weight: 600;
    letter-spacing: 2px;
}

.nav-links {
    display: flex;
    gap: 2.5rem;
}

.nav-links a {
    font-size: 0.9rem;
    font-weight: 400;
}

.nav-links a:hover {
    color: var(--accent-color);
}

.nav-icons {
    display: flex;
    gap: 1.5rem;
}

.nav-icons button {
    background: none;
    border: none;
    cursor: pointer;
    position: relative;
    color: var(--primary-color);
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -10px;
    background-color: var(--primary-color);
    color: white;
    font-size: 0.7rem;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Hero Section */
.hero {
    height: 80vh;
    background-image: linear-gradient(rgba(0,0,0,0.1), rgba(0,0,0,0.1)), url('https://images.unsplash.com/photo-1449247704656-13621df5ee70?q=80&w=2000&auto=format&fit=crop');
    background-size: cover;
    background-position: center;
    display: flex;
    align-items: center;
    color: var(--primary-color);
}

.hero-content {
    max-width: 600px;
}

.hero h1 {
    font-size: 3.5rem;
    line-height: 1.1;
    margin-bottom: 1.5rem;
    font-weight: 400;
}

.hero p {
    font-size: 1.1rem;
    margin-bottom: 2rem;
    color: #444;
}

/* Product Grid */
.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 3rem;
}

.section-header h2 {
    font-size: 2rem;
    font-weight: 500;
}

.view-all {
    font-size: 0.9rem;
    border-bottom: 1px solid var(--primary-color);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    transition: var(--transition);
}

.product-image {
    background-color: #fff;
    aspect-ratio: 4/5;
    overflow: hidden;
    margin-bottom: 1rem;
    position: relative;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info h3 {
    font-size: 1rem;
    font-weight: 400;
    margin-bottom: 0.5rem;
}

.price {
    font-weight: 600;
    margin-bottom: 1rem;
}

.btn-add-cart {
    width: 100%;
    padding: 0.6rem;
    background: transparent;
    border: 1px solid var(--primary-color);
    cursor: pointer;
    transition: var(--transition);
}

.btn-add-cart:hover {
    background: var(--primary-color);
    color: var(--secondary-color);
}

/* Deals Section */
.deals-section {
    background-color: var(--primary-color);
    color: var(--secondary-color);
}

.deals-banner {
    display: flex;
    justify-content: center;
    text-align: center;
}

.deals-content {
    max-width: 700px;
}

.deals-content .badge {
    background-color: rgba(255,255,255,0.1);
    color: white;
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1.5rem;
}

.countdown {
    display: flex;
    justify-content: center;
    gap: 2rem;
    margin: 2.5rem 0;
}

.time-block {
    display: flex;
    flex-direction: column;
}

.time-block span {
    font-size: 2rem;
    font-weight: 600;
}

.time-block small {
    font-size: 0.8rem;
    text-transform: uppercase;
    opacity: 0.7;
}

/* Newsletter */
.newsletter-box {
    background-color: white;
    padding: 4rem;
    text-align: center;
    border: 1px solid var(--light-gray);
}

.newsletter-box h2 {
    margin-bottom: 1rem;
}

.newsletter-box p {
    margin-bottom: 2rem;
    color: var(--accent-color);
}

#newsletter-form {
    display: flex;
    max-width: 500px;
    margin: 0 auto;
    gap: 0.5rem;
}

#newsletter-form input {
    flex: 1;
    padding: 0.8rem;
    border: 1px solid var(--light-gray);
    outline: none;
}

/* Footer */
footer {
    background-color: var(--secondary-color);
    padding-top: 5rem;
    border-top: 1px solid var(--light-gray);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-info p {
    margin-top: 1.5rem;
    max-width: 250px;
    color: var(--accent-color);
}

.footer-links h4 {
    margin-bottom: 1.5rem;
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 1px;
}

.footer-links ul li {
    margin-bottom: 0.8rem;
}

.footer-links a {
    color: var(--accent-color);
    font-size: 0.9rem;
}

.footer-links a:hover {
    color: var(--primary-color);
}

.footer-bottom {
    padding: 2rem 0;
    border-top: 1px solid var(--light-gray);
    text-align: center;
    font-size: 0.8rem;
    color: var(--accent-color);
}

/* Responsive */
@media (max-width: 992px) {
    .footer-grid {
        grid-template-columns: 1fr 1fr;
    }
    .hero h1 {
        font-size: 2.5rem;
    }
}

@media (max-width: 768px) {
    .nav-links {
        display: none;
    }
    .hero {
        height: 60vh;
    }
    .newsletter-box {
        padding: 2rem;
    }
    #newsletter-form {
        flex-direction: column;
    }
    .footer-grid {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
}
