}

.deals-banner {
    display: flex;
    justify-content: center;
    text-align: center;
}

.deals-content {
    max-width: 700px;
}

.deals-content .badge {
    background-color: rgba(255,255,255,0.1);
    color: white;
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1.5rem;
}

.countdown {
    display: flex;
    justify-content: center;
    gap: 2rem;
    margin: 2.5rem 0;
}

.time-block {
    display: flex;
    flex-direction: column;
}

.time-block span {
    font-size: 2rem;
    font-weight: 600;
}

.time-block small {
    font-size: 0.8rem;
    text-transform: uppercase;
    opacity: 0.7;
}

/* Newsletter */
.newsletter-box {
    background-color: white;
    padding: 4rem;
    text-align: center;
    border: 1px solid var(--light-gray);
}

.newsletter-box h2 {
    margin-bottom: 1rem;
}

.newsletter-box p {
    margin-bottom: 2rem;
    color: var(--accent-color);
}

#newsletter-form {
    display: flex;
    max-width: 500px;
    margin: 0 auto;
    gap: 0.5rem;
}

#newsletter-form input {
    flex: 1;
    padding: 0.8rem;
    border: 1px solid var(--light-gray);
    outline: none;
}

/* Footer */
footer {
    background-color: var(--secondary-color);
    padding-top: 5rem;
    border-top: 1px solid var(--light-gray);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-info p {
    margin-top: 1.5rem;
    max-width: 250px;
    color: var(--accent-color);
}

.footer-links h4 {
    margin-bottom: 1.5rem;
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 1px;
}

.footer-links ul li {
    margin-bottom: 0.8rem;
}

.footer-links a {
    color: var(--accent-color);
    font-size: 0.9rem;
}

.footer-links a:hover {
    color: var(--primary-color);
}

.footer-bottom {
    padding: 2rem 0;
    border-top: 1px solid var(--light-gray);
    text-align: center;
    font-size: 0.8rem;
    color: var(--accent-color);
}

/* Responsive */
@media (max-width: 992px) {
